import bpy,bmesh,os,json
r=os.path.dirname(os.path.dirname(os.path.abspath(__file__)));out={}
for mode in ['material','white']:
 bpy.ops.wm.open_mainfile(filepath=r+'/models/'+mode+'.blend');o=bpy.data.objects['SIGN_QQ炫舞_font_proxy'];b=bmesh.new();b.from_mesh(o.data);bad=[f for f in b.faces if len(f.verts)==3 and ((f.verts[1].co-f.verts[0].co).cross(f.verts[2].co-f.verts[0].co)).length<2e-12];oldcoords=sorted(tuple(v.co) for v in b.verts);badcoords=[[list(v.co) for v in f.verts] for f in bad];bmesh.ops.dissolve_faces(b,faces=bad,use_verts=False);bmesh.ops.recalc_face_normals(b,faces=list(b.faces));stats={'v':len(b.verts),'e':len(b.edges),'f':len(b.faces),'nonmanifold':sum(not e.is_manifold for e in b.edges),'volume':b.calc_volume(signed=True),'exact_vertex_multiset_equal':oldcoords==sorted(tuple(v.co) for v in b.verts)};b.to_mesh(o.data);b.free();o.data.calc_loop_triangles();ar=[((o.data.vertices[t.vertices[1]].co-o.data.vertices[t.vertices[0]].co).cross(o.data.vertices[t.vertices[2]].co-o.data.vertices[t.vertices[0]].co)).length/2 for t in o.data.loop_triangles];out[mode]={'dissolved_exact_collinear_face_coordinates':badcoords,'stats':stats,'zero_loop_triangles':sum(a<1e-12 for a in ar),'min_triangle_area':min(ar)};bpy.ops.wm.save_as_mainfile(filepath=r+'/models/'+mode+'.blend');bpy.ops.export_scene.gltf(filepath=r+'/models/'+mode+'.glb',export_format='GLB',export_cameras=True,export_lights=False)
json.dump(out,open(r+'/qa/sign-exact-collinear-r03.json','w'),indent=2);print(out)
